 int n;
 std::cin >> x >> n;
 if (x == 0 && n <= 0) {
 std::cout << "Nieokreslony przypadek\n";
 return 1;
 }
 double wynik = 1.0;
 long long e = n;
 if (e < 0) e = -e;
 for (long long i = 0; i < e; ++i) wynik = x;
 if (n < 0) wynik = 1.0 / wynik;
 std::cout << wynik << '\n';
}

